    60	static int
    61	label (const uint8_t * src, size_t srclen, uint8_t * dst, size_t * dstlen,
    62	       int flags)
    63	{
    64	  size_t plen;
    65	  uint32_t *p;
    66	  int rc;
    67	  size_t tmpl;
    68	
    69	  if (_idn2_ascii_p (src, srclen))
    70	    {
    71	      if (flags & IDN2_ALABEL_ROUNDTRIP)
    72	        /* FIXME implement this MAY:
    73	
    74	           If the input to this procedure appears to be an A-label
    75	           (i.e., it starts in "xn--", interpreted
    76	           case-insensitively), the lookup application MAY attempt to
    77	           convert it to a U-label, first ensuring that the A-label is
    78	           entirely in lowercase (converting it to lowercase if
    79	           necessary), and apply the tests of Section 5.4 and the
    80	           conversion of Section 5.5 to that form. */
    81	        return IDN2_INVALID_FLAGS;
    82	
    83	      if (srclen > IDN2_LABEL_MAX_LENGTH)
    84	        return IDN2_TOO_BIG_LABEL;
    85	      if (srclen > *dstlen)
    86	        return IDN2_TOO_BIG_DOMAIN;
    87	
    88	      memcpy (dst, src, srclen);
    89	      *dstlen = srclen;
    90	      return IDN2_OK;
    91	    }
    92	
    93	  rc = _idn2_u8_to_u32_nfc (src, srclen, &p, &plen, flags & IDN2_NFC_INPUT);
    94	  if (rc != IDN2_OK)
    95	    return rc;
    96	
    97	  if (!(flags & IDN2_TRANSITIONAL))
    98	    {
    99	      rc = _idn2_label_test(
   100	        TEST_NFC |
   101	        TEST_2HYPHEN |
   102	        TEST_LEADING_COMBINING |
   103	        TEST_DISALLOWED |
   104	        TEST_CONTEXTJ_RULE |
   105	        TEST_CONTEXTO_WITH_RULE |
   106	        TEST_UNASSIGNED | TEST_BIDI |
   107	        ((flags & IDN2_NONTRANSITIONAL) ? TEST_NONTRANSITIONAL : 0) |
   108	        ((flags & IDN2_USE_STD3_ASCII_RULES) ? 0 : TEST_ALLOW_STD3_DISALLOWED),
   109	        p, plen);
   110	
   111	      if (rc != IDN2_OK)
   112	        {
   113	          free(p);
   114	          return rc;
   115	        }
   116	    }
   117	
   118	  dst[0] = 'x';
   119	  dst[1] = 'n';
   120	  dst[2] = '-';
   121	  dst[3] = '-';
   122	
   123	  tmpl = *dstlen - 4;
   124	  rc = _idn2_punycode_encode (plen, p, &tmpl, (char *) dst + 4);
   125	  free (p);
   126	  if (rc != IDN2_OK)
   127	    return rc;
   128	
   129	  *dstlen = 4 + tmpl;
   130	
   131	  return IDN2_OK;
   132	}
   133	
   134	#define TR46_TRANSITIONAL_CHECK \
   135	  (TEST_NFC | TEST_2HYPHEN | TEST_HYPHEN_STARTEND | TEST_LEADING_COMBINING | TEST_TRANSITIONAL)
   136	#define TR46_NONTRANSITIONAL_CHECK \
   137	  (TEST_NFC | TEST_2HYPHEN | TEST_HYPHEN_STARTEND | TEST_LEADING_COMBINING | TEST_NONTRANSITIONAL)
   138	
   139	static int
   140	_tr46 (const uint8_t * domain_u8, uint8_t ** out, int flags)
   141	{
   142	  size_t len, it;
   143	  uint32_t *domain_u32;
   144	  int err = IDN2_OK, rc;
   145	  int transitional = 0;
   146	  int test_flags;
   147	
   148	  if (flags & IDN2_TRANSITIONAL)
   149	    transitional = 1;
   150	
   151	  /* convert UTF-8 to UTF-32 */
   152	  if (!(domain_u32 =
   153	       u8_to_u32 (domain_u8, u8_strlen (domain_u8) + 1, NULL, &len)))
   154	    {
   155	      if (errno == ENOMEM)
   156	        return IDN2_MALLOC;
   157	      return IDN2_ENCODING_ERROR;
   158	    }
   159	
   160	  size_t len2 = 0;
   161	  for (it = 0; it < len - 1; it++)
   162	    {
   163	      IDNAMap map;
   164	
   165	      get_idna_map (domain_u32[it], &map);
   166	
   167	      if (map_is (&map, TR46_FLG_DISALLOWED))
   168	        {
   169	          if (domain_u32[it])
   170	            {
   171	              free (domain_u32);
   172	              return IDN2_DISALLOWED;
   173	            }
   174	          len2++;
   175	        }
   176	      else if (map_is (&map, TR46_FLG_MAPPED))
   177	        {
   178	          len2 += map.nmappings;
   179	        }
   180	      else if (map_is (&map, TR46_FLG_VALID))
   181	        {
   182	          len2++;
   183	        }
   184	      else if (map_is (&map, TR46_FLG_IGNORED))
   185	        {
   186	          continue;
   187	        }
   188	      else if (map_is (&map, TR46_FLG_DEVIATION))
   189	        {
   190	          if (transitional)
   191	            {
   192	              len2 += map.nmappings;
   193	            }
   194	          else
   195	            len2++;
   196	        }
   197	      else if (!(flags & IDN2_USE_STD3_ASCII_RULES))
   198	        {
   199	          if (map_is (&map, TR46_FLG_DISALLOWED_STD3_VALID))
   200	            {
   201	              /* valid because UseSTD3ASCIIRules=false, see #TR46 5 */
   202	              len2++;
   203	            }
   204	          else if (map_is (&map, TR46_FLG_DISALLOWED_STD3_MAPPED))
   205	            {
   206	              /* mapped because UseSTD3ASCIIRules=false, see #TR46 5 */
   207	              len2 += map.nmappings;
   208	            }
   209	        }
   210	    }
   211	
   212	  /* Exit early if result is too long.
   213	   * This avoids excessive CPU usage in punycode encoding, which is O(N^2). */
   214	  if (len2 >= IDN2_DOMAIN_MAX_LENGTH)
   215	    {
   216	      free (domain_u32);
   217	      return IDN2_TOO_BIG_DOMAIN;
   218	    }
   219	
   220	  uint32_t *tmp = (uint32_t *) malloc ((len2 + 1) * sizeof (uint32_t));
   221	  if (!tmp)
   222	    {
   223	      free (domain_u32);
   224	      return IDN2_MALLOC;
   225	    }
   226	
   227	  len2 = 0;
   228	  for (it = 0; it < len - 1; it++)
   229	    {
   230	      uint32_t c = domain_u32[it];
   231	      IDNAMap map;
   232	
   233	      get_idna_map (c, &map);
   234	
   235	      if (map_is (&map, TR46_FLG_DISALLOWED))
   236	        {
   237	          tmp[len2++] = c;
   238	        }
   239	      else if (map_is (&map, TR46_FLG_MAPPED))
   240	        {
   241	          len2 += get_map_data (tmp + len2, &map);
   242	        }
   243	      else if (map_is (&map, TR46_FLG_VALID))
   244	        {
   245	          tmp[len2++] = c;
   246	        }
   247	      else if (map_is (&map, TR46_FLG_IGNORED))
   248	        {
   249	          continue;
   250	        }
   251	      else if (map_is (&map, TR46_FLG_DEVIATION))
   252	        {
   253	          if (transitional)
   254	            {
   255	              len2 += get_map_data (tmp + len2, &map);
   256	            }
   257	          else
   258	            tmp[len2++] = c;
   259	        }
   260	      else if (!(flags & IDN2_USE_STD3_ASCII_RULES))
   261	        {
   262	          if (map_is (&map, TR46_FLG_DISALLOWED_STD3_VALID))
   263	            {
   264	              tmp[len2++] = c;
   265	            }
   266	          else if (map_is (&map, TR46_FLG_DISALLOWED_STD3_MAPPED))
   267	            {
   268	              len2 += get_map_data (tmp + len2, &map);
   269	            }
   270	        }
   271	    }
   272	  free (domain_u32);
   273	
   274	  /* Normalize to NFC */
   275	  tmp[len2] = 0;
   276	  domain_u32 = u32_normalize (UNINORM_NFC, tmp, len2 + 1, NULL, &len);
   277	  free (tmp);
   278	  tmp = NULL;
   279	
   280	  if (!domain_u32)
   281	    {
   282	      if (errno == ENOMEM)
   283	        return IDN2_MALLOC;
   284	      return IDN2_ENCODING_ERROR;
   285	    }
   286	
   287	  /* split into labels and check */
   288	  uint32_t *e, *s;
   289	  for (e = s = domain_u32; *e; s = e)
   290	    {
   291	      while (*e && *e != '.')
   292	        e++;
   293	
   294	      if (e - s >= 4 && s[0] == 'x' && s[1] == 'n' && s[2] == '-'
   295	          && s[3] == '-')
   296	        {
   297	          /* decode punycode and check result non-transitional */
   298	          size_t ace_len;
   299	          uint32_t name_u32[IDN2_LABEL_MAX_LENGTH];
   300	          size_t name_len = IDN2_LABEL_MAX_LENGTH;
   301	          uint8_t *ace;
   302	
   303	          ace = u32_to_u8 (s + 4, e - s - 4, NULL, &ace_len);
   304	          if (!ace)
   305	            {
   306	              free (domain_u32);
   307	              if (errno == ENOMEM)
   308	                return IDN2_MALLOC;
   309	              return IDN2_ENCODING_ERROR;
   310	            }
   311	
   312	          rc =
   313	            _idn2_punycode_decode (ace_len, (char *) ace, &name_len, name_u32);
   314	
   315	          free (ace);
   316	
   317	          if (rc)
   318	            {
   319	              free (domain_u32);
   320	              return rc;
   321	            }
   322	
   323	          test_flags = TR46_NONTRANSITIONAL_CHECK;
   324	
   325	          if (!(flags & IDN2_USE_STD3_ASCII_RULES))
   326	            test_flags |= TEST_ALLOW_STD3_DISALLOWED;
   327	
   328	          if ((rc =
   329	               _idn2_label_test (test_flags, name_u32,
   330	                                 name_len)))
   331	            err = rc;
   332	        }
   333	      else
   334	        {
   335	          test_flags = transitional ? TR46_TRANSITIONAL_CHECK : TR46_NONTRANSITIONAL_CHECK;
   336	
   337	          if (!(flags & IDN2_USE_STD3_ASCII_RULES))
   338	            test_flags |= TEST_ALLOW_STD3_DISALLOWED;
   339	
   340	          if ((rc =
   341	               _idn2_label_test (test_flags, s, e - s)))
   342	            err = rc;
   343	        }
   344	
   345	      if (*e)
   346	        e++;
   347	    }
   348	
   349	  if (err == IDN2_OK && out)
   350	    {
   351	      uint8_t *_out = u32_to_u8 (domain_u32, len, NULL, &len);
   352	      free (domain_u32);
   353	
   354	      if (!_out)
   355	        {
   356	          if (errno == ENOMEM)
   357	            return IDN2_MALLOC;
   358	          return IDN2_ENCODING_ERROR;
   359	        }
   360	
   361	      *out = _out;
   362	    }
   363	  else
   364	    free (domain_u32);
   365	
   366	  return err;
   367	}
   368	
   369	/**
   370	 * idn2_lookup_u8:
   371	 * @src: input zero-terminated UTF-8 string in Unicode NFC normalized form.
   372	 * @lookupname: newly allocated output variable with name to lookup in DNS.
   373	 * @flags: optional #idn2_flags to modify behaviour.
   374	 *
   375	 * Perform IDNA2008 lookup string conversion on domain name @src, as
   376	 * described in section 5 of RFC 5891.  Note that the input string
   377	 * must be encoded in UTF-8 and be in Unicode NFC form.
   378	 *
   379	 * Pass %IDN2_NFC_INPUT in @flags to convert input to NFC form before
   380	 * further processing.  %IDN2_TRANSITIONAL and %IDN2_NONTRANSITIONAL
   381	 * do already imply %IDN2_NFC_INPUT.
   382	 * Pass %IDN2_ALABEL_ROUNDTRIP in @flags to
   383	 * convert any input A-labels to U-labels and perform additional
   384	 * testing (not implemented yet).
   385	 * Pass %IDN2_TRANSITIONAL to enable Unicode TR46
   386	 * transitional processing, and %IDN2_NONTRANSITIONAL to enable
   387	 * Unicode TR46 non-transitional processing.  Multiple flags may be
   388	 * specified by binary or:ing them together.
   389	 *
   390	 * After version 2.0.3: %IDN2_USE_STD3_ASCII_RULES disabled by default.
   391	 * Previously we were eliminating non-STD3 characters from domain strings
   392	 * such as _443._tcp.example.com, or IPs 1.2.3.4/24 provided to libidn2
   393	 * functions. That was an unexpected regression for applications switching
   394	 * from libidn and thus it is no longer applied by default.
   395	 * Use %IDN2_USE_STD3_ASCII_RULES to enable that behavior again.
   396	 *
   397	 * After version 0.11: @lookupname may be NULL to test lookup of @src
   398	 * without allocating memory.
   399	 *
   400	 * Returns: On successful conversion %IDN2_OK is returned, if the
   401	 *   output domain or any label would have been too long
   402	 *   %IDN2_TOO_BIG_DOMAIN or %IDN2_TOO_BIG_LABEL is returned, or
   403	 *   another error code is returned.
   404	 *
   405	 * Since: 0.1
   406	 **/
   407	int
   408	idn2_lookup_u8 (const uint8_t * src, uint8_t ** lookupname, int flags)
   409	{
   410	  size_t lookupnamelen = 0;
   411	  uint8_t _lookupname[IDN2_DOMAIN_MAX_LENGTH + 1];
   412	  uint8_t _mapped[IDN2_DOMAIN_MAX_LENGTH + 1];
   413	  int rc;
   414	
   415	  if (src == NULL)
   416	    {
   417	      if (lookupname)
   418	        *lookupname = NULL;
   419	      return IDN2_OK;
   420	    }
   421	
   422	  rc = set_default_flags(&flags);
   423	  if (rc != IDN2_OK)
   424	    return rc;
   425	
   426	  if (!(flags & IDN2_NO_TR46))
   427	    {
   428	      uint8_t *out;
   429	      size_t outlen;
   430	
   431	      rc = _tr46 (src, &out, flags);
   432	      if (rc != IDN2_OK)
   433	        return rc;
   434	
   435	      outlen = u8_strlen (out);
   436	      if (outlen >= sizeof (_mapped))
   437	        {
   438	          free (out);
   439	          return IDN2_TOO_BIG_DOMAIN;
   440	        }
   441	
   442	      memcpy (_mapped, out, outlen + 1);
   443	      src = _mapped;
   444	      free (out);
   445	    }
   446	
   447	  do
   448	    {
   449	      const uint8_t *end = (uint8_t *) strchrnul ((const char *) src, '.');
   450	      /* XXX Do we care about non-U+002E dots such as U+3002, U+FF0E
   451	         and U+FF61 here?  Perhaps when IDN2_NFC_INPUT? */
   452	      size_t labellen = end - src;
   453	      uint8_t tmp[IDN2_LABEL_MAX_LENGTH];
   454	      size_t tmplen = IDN2_LABEL_MAX_LENGTH;
   455	
   456	      rc = label (src, labellen, tmp, &tmplen, flags);
   457	      if (rc != IDN2_OK)
   458	        return rc;
   459	
   460	      if (lookupnamelen + tmplen
   461	          > IDN2_DOMAIN_MAX_LENGTH - (tmplen == 0 && *end == '\0' ? 1 : 2))
   462	        return IDN2_TOO_BIG_DOMAIN;
   463	
   464	      memcpy (_lookupname + lookupnamelen, tmp, tmplen);
   465	      lookupnamelen += tmplen;
   466	
   467	      if (*end == '.')
   468	        {
   469	          if (lookupnamelen + 1 > IDN2_DOMAIN_MAX_LENGTH)
   470	            return IDN2_TOO_BIG_DOMAIN;
   471	
   472	          _lookupname[lookupnamelen] = '.';
   473	          lookupnamelen++;
   474	        }
   475	      _lookupname[lookupnamelen] = '\0';
   476	
   477	      src = end;
   478	    }
   479	  while (*src++);
   480	
   481	  if (lookupname)
   482	    {
   483	      uint8_t *tmp = (uint8_t *) malloc (lookupnamelen + 1);
   484	
   485	      if (tmp == NULL)
   486	        return IDN2_MALLOC;
   487	
   488	      memcpy (tmp, _lookupname, lookupnamelen + 1);
   489	      *lookupname = tmp;
   490	    }
   491	
   492	  return IDN2_OK;
   493	}
